INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2120228, 290246, 21611, '<td valign="top">Very nice idea well done and very creative 10.</td>', 'Very nice idea well done and very creative 10.', '2006-02-03 22:25:47.000000', NULL, 1),
(2120230, 290155, 21611, '<td valign="top">Excellent work nice ideas and very creative</td>', 'Excellent work nice ideas and very creative', '2006-02-03 22:26:21.000000', NULL, 1),
(2120231, 290153, 21611, '<td valign="top">Maybe this time..... good job and nice work</td>', 'Maybe this time..... good job and nice work', '2006-02-03 22:26:51.000000', NULL, 1),
(2120234, 289961, 21611, '<td valign="top">nice use of shadows very creative, one of only a handful of shots to show the shadow falling on the subject. Excellent work good luuck</td>', 'nice use of shadows very creative, one of only a handful of shots to show the shadow falling on the subject. Excellent work good luuck', '2006-02-03 22:27:52.000000', NULL, 1),
(2120256, 289920, 40718, '<td valign="top">Shadow was a tough challenge.  Personally I was looking for images that had more to the story than just "the shadow".  Of this type, I actually thought this was one of the better ones.  You added color which gave interest and I do like the repeated pattern of your face.  The extra shadows in the lower right should be gone as they confuse our eyes.  Even the largest version of you (where your eye is way up in the top right) is a bit distracting because it doesn''t "mesh" with the pattern of the other faces which move lower as they get bigger.<br/> <br/>Exposure is nice.  I wonder if a bit more contrast might give more pop without destroying some of the delicate detail.  I gave it a 5, but lots of other shots like this got 4 or lower from me.</td>', 'Shadow was a tough challenge.  Personally I was looking for images that had more to the story than just "the shadow".  Of this type, I actually thought this was one of the better ones.  You added color which gave interest and I do like the repeated pattern of your face.  The extra shadows in the lower right should be gone as they confuse our eyes.  Even the largest version of you (where your eye is way up in the top right) is a bit distracting because it doesn''t "mesh" with the pattern of the other faces which move lower as they get bigger. Exposure is nice.  I wonder if a bit more contrast might give more pop without destroying some of the delicate detail.  I gave it a 5, but lots of other shots like this got 4 or lower from me.', '2006-02-03 22:41:12.000000', NULL, 1),
(2120301, 290161, 42638, '<td valign="top">Very creative, love the idea. Excelent composition</td>', 'Very creative, love the idea. Excelent composition', '2006-02-03 22:59:39.000000', NULL, 1),
(2120346, 290335, 15511, '<td valign="top">Cool, but jus'' a bit too dark.</td>', 'Cool, but jus'' a bit too dark.', '2006-02-03 23:21:13.000000', NULL, 1),
