(2123107, 290105, 28882, '<td valign="top">good drama.  the halo of the shadow from a second light source is a little distracting though.</td>', 'good drama.  the halo of the shadow from a second light source is a little distracting though.', '2006-02-05 00:58:12.000000', NULL, 1),
(2123111, 290100, 28882, '<td valign="top">i like the look of the wall and the depth of the shadow.  If the pose were more intesting it would help.</td>', 'i like the look of the wall and the depth of the shadow.  If the pose were more intesting it would help.', '2006-02-05 00:59:56.000000', NULL, 1),
(2123113, 290154, 28882, '<td valign="top">nice drama and textures, a little too dark for me though.</td>', 'nice drama and textures, a little too dark for me though.', '2006-02-05 01:00:44.000000', NULL, 1),
