INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2123123, 290300, 28882, '<td valign="top">creative</td>', 'creative', '2006-02-05 01:05:28.000000', NULL, 1),
(2123136, 290107, 28882, '<td valign="top">i like that you included the shadow but didn''t neglect the rest of the picture.</td>', 'i like that you included the shadow but didn''t neglect the rest of the picture.', '2006-02-05 01:11:23.000000', NULL, 1),
(2123193, 290246, 42638, '<td valign="top">Very nice, Good imagination. Love the use of light here, it also doubles as a setting sun. Wonderful composition.</td>', 'Very nice, Good imagination. Love the use of light here, it also doubles as a setting sun. Wonderful composition.', '2006-02-05 01:35:04.000000', NULL, 1),
(2123198, 289907, 42638, '<td valign="top">Very nice and well defined. Good use of space.</td>', 'Very nice and well defined. Good use of space.', '2006-02-05 01:38:13.000000', NULL, 1),
(2123199, 289913, 42638, '<td valign="top">Very nice. Love the imagination here, great execution.</td>', 'Very nice. Love the imagination here, great execution.', '2006-02-05 01:39:03.000000', NULL, 1),
(2123465, 290271, 10858, '<td valign="top">I love this one. Both the idea and the implementation are great, and lighting is spot on! Good luck!</td>', 'I love this one. Both the idea and the implementation are great, and lighting is spot on! Good luck!', '2006-02-05 04:47:24.000000', NULL, 1),
(2123469, 290155, 10858, '<td valign="top">Great one! The coloursare stunning, and the composition is the best for this subject. I also like the reflections in the water. Good luck!</td>', 'Great one! The coloursare stunning, and the composition is the best for this subject. I also like the reflections in the water. Good luck!', '2006-02-05 04:52:37.000000', NULL, 1),
(2123471, 289945, 10858, '<td valign="top">Simple but great! BW works well, I also like the composition. The boy''s expression is talkative and reflects both curiousity and uncertainnes because of the relationship with the shadow.</td>', 'Simple but great! BW works well, I also like the composition. The boy''s expression is talkative and reflects both curiousity and uncertainnes because of the relationship with the shadow.', '2006-02-05 04:55:06.000000', NULL, 1),
(2123473, 290084, 10858, '<td valign="top">It''s quite difficult to figure out the story without the title. OOF and the curtain both have rather a negative effect on this IMO, however the idea must have been good.</td>', 'It''s quite difficult to figure out the story without the title. OOF and the curtain both have rather a negative effect on this IMO, however the idea must have been good.', '2006-02-05 04:56:53.000000', NULL, 1),
(2123475, 290277, 10858, '<td valign="top">Very moody capture, bit depressive, but it''s great. Exposure, lighting and colours work well in a harmony for the subject.</td>', 'Very moody capture, bit depressive, but it''s great. Exposure, lighting and colours work well in a harmony for the subject.', '2006-02-05 04:59:56.000000', NULL, 1),
(2123558, 290155, 40820, '<td valign="top">this has to be my favorite shot in this challenge..great idea...stunning spot!...good luck...9</td>', 'this has to be my favorite shot in this challenge..great idea...stunning spot!...good luck...9', '2006-02-05 07:08:20.000000', NULL, 1),
(2123559, 290213, 40820, '<td valign="top">excellent idea..great composition..good luck..8</td>', 'excellent idea..great composition..good luck..8', '2006-02-05 07:10:22.000000', NULL, 1),
(2123561, 289976, 40820, '<td valign="top">haha...great interpretation...excellent lighting and color tones...good luck..8</td>', 'haha...great interpretation...excellent lighting and color tones...good luck..8', '2006-02-05 07:11:24.000000', NULL, 1),
(2123613, 290262, 47852, '<td valign="top">An interestingly shaped shadow, but the challenge asked for your shadow.  Even if you would have added your hand picking up a glass, or touching the figure in some way it would have better met the criteria.</td>', 'An interestingly shaped shadow, but the challenge asked for your shadow.  Even if you would have added your hand picking up a glass, or touching the figure in some way it would have better met the criteria.', '2006-02-05 08:13:52.000000', NULL, 1),
(2123620, 290316, 47852, '<td valign="top">The actual shadow takes up most of the shot, and you can''t see the edges enough to make out the shape of the shadow.  Perhaps turning your body slightly towards the camera and pulling your light source a little closer would have created a tighter "sensual shadow".</td>', 'The actual shadow takes up most of the shot, and you can''t see the edges enough to make out the shape of the shadow.  Perhaps turning your body slightly towards the camera and pulling your light source a little closer would have created a tighter "sensual shadow".', '2006-02-05 08:16:41.000000', NULL, 1),
(2123622, 289976, 47852, '<td valign="top">Fantastic shot and great morphing of the shadow.  One of my top picks for the challenge!</td>', 'Fantastic shot and great morphing of the shadow.  One of my top picks for the challenge!', '2006-02-05 08:17:26.000000', NULL, 1),
(2123624, 290285, 47852, '<td valign="top">Great colors and lines here.  The shadow (silhouette?) is very crisp and well defined.  Well done.</td>', 'Great colors and lines here.  The shadow (silhouette?) is very crisp and well defined.  Well done.', '2006-02-05 08:19:04.000000', NULL, 1),
(2123628, 290271, 47852, '<td valign="top">Almost like the new commercials they have out... was that where you got the inspiration?  Well done!</td>', 'Almost like the new commercials they have out... was that where you got the inspiration?  Well done!', '2006-02-05 08:19:54.000000', NULL, 1),
(2123631, 290155, 47852, '<td valign="top">Very pretty colors in this one.  I love how your shadow reflects in the water too, and that you found a spot where the only other shadow was the tree.  Very nicely done!</td>', 'Very pretty colors in this one.  I love how your shadow reflects in the water too, and that you found a spot where the only other shadow was the tree.  Very nicely done!', '2006-02-05 08:21:00.000000', NULL, 1),
(2123634, 290228, 8624, '<td valign="top">I wish this was a little bigger to be able to see more detail. I like the shadow silouette, very sad. I think it might have worked beter without the flowers in the foreground.</td>', 'I wish this was a little bigger to be able to see more detail. I like the shadow silouette, very sad. I think it might have worked beter without the flowers in the foreground.', '2006-02-05 08:21:33.000000', NULL, 1),
(2123637, 290025, 47852, '<td valign="top">Ok, I looked at this one for a while trying to figure out how you did it.  If this really is a self portrait it was perfect timing.</td>', 'Ok, I looked at this one for a while trying to figure out how you did it.  If this really is a self portrait it was perfect timing.', '2006-02-05 08:22:29.000000', NULL, 1),
(2123640, 290252, 8624, '<td valign="top">nicely done, although the shadows of the apples are darker, making me think they were a different distance from your light source, spoiling the illusion somewhat</td>', 'nicely done, although the shadows of the apples are darker, making me think they were a different distance from your light source, spoiling the illusion somewhat', '2006-02-05 08:23:04.000000', NULL, 1),
(2123642, 290061, 47852, '<td valign="top">Simple yet very clever.  Strangely, the one thing I like about this shot is how the slight reflection of the coffee cup makes a line where your thumbnail would be.  Makes it look just a touch more real instead of just a shadow.  Nice job!</td>', 'Simple yet very clever.  Strangely, the one thing I like about this shot is how the slight reflection of the coffee cup makes a line where your thumbnail would be.  Makes it look just a touch more real instead of just a shadow.  Nice job!', '2006-02-05 08:23:48.000000', NULL, 1),
(2123646, 290325, 8624, '<td valign="top">great idea. I think this would have looked better on a more colorful wall (asumming you didn''t just desaturate here) to get more of the iPod commercial feel.</td>', 'great idea. I think this would have looked better on a more colorful wall (asumming you didn''t just desaturate here) to get more of the iPod commercial feel.', '2006-02-05 08:25:00.000000', NULL, 1),
(2123647, 290078, 42638, '<td valign="top">Very nice. Love the composition, really tells a tale.</td>', 'Very nice. Love the composition, really tells a tale.', '2006-02-05 08:25:06.000000', NULL, 1),
(2123648, 290180, 8624, '<td valign="top">nothing let of you but a scorched shadow on the wall...</td>', 'nothing let of you but a scorched shadow on the wall...', '2006-02-05 08:25:42.000000', NULL, 1),
(2123649, 290129, 42638, '<td valign="top">Fantastic shadow. Good composition and use of space. Love the B&amp;W.</td>', 'Fantastic shadow. Good composition and use of space. Love the B&W.', '2006-02-05 08:25:57.000000', NULL, 1),
(2123651, 289945, 42638, '<td valign="top">Nicely done. Love the idea, very inquisitive feel.</td>', 'Nicely done. Love the idea, very inquisitive feel.', '2006-02-05 08:26:10.000000', NULL, 1),
(2123652, 290025, 42638, '<td valign="top">Good imagination and execution. Love it!</td>', 'Good imagination and execution. Love it!', '2006-02-05 08:26:13.000000', NULL, 1),
(2123653, 290285, 42638, '<td valign="top">Interesting color here, I really like the almost perfect silhouette and the lines. Well done.</td>', 'Interesting color here, I really like the almost perfect silhouette and the lines. Well done.', '2006-02-05 08:26:16.000000', NULL, 1),
(2123654, 290246, 8624, '<td valign="top">fantastic. love your creativitiy here with the pose and using your light as the setting sun. I hope this ribbons.</td>', 'fantastic. love your creativitiy here with the pose and using your light as the setting sun. I hope this ribbons.', '2006-02-05 08:26:24.000000', NULL, 1),
(2123655, 290330, 42638, '<td valign="top">Very nice, Love the crispness here. How fun.</td>', 'Very nice, Love the crispness here. How fun.', '2006-02-05 08:26:51.000000', NULL, 1),
(2123657, 290271, 42638, '<td valign="top">Fantastic, Love the title and execution of this.</td>', 'Fantastic, Love the title and execution of this.', '2006-02-05 08:27:32.000000', NULL, 1),
(2123658, 290300, 8624, '<td valign="top">I am interested to see how you made the devil shadow. well done.</td>', 'I am interested to see how you made the devil shadow. well done.', '2006-02-05 08:27:50.000000', NULL, 1),
(2123659, 290165, 42638, '<td valign="top">Very creative, good imagination and composition.</td>', 'Very creative, good imagination and composition.', '2006-02-05 08:27:56.000000', NULL, 1),
(2123660, 290213, 42638, '<td valign="top">Wow, love the lines of light from the water, Really frames the shadow well.</td>', 'Wow, love the lines of light from the water, Really frames the shadow well.', '2006-02-05 08:28:35.000000', NULL, 1),
(2123662, 289976, 42638, '<td valign="top">Wow, how did you do this one. Very nice compostion, good lighting.</td>', 'Wow, how did you do this one. Very nice compostion, good lighting.', '2006-02-05 08:29:18.000000', NULL, 1),
(2123663, 290226, 8624, '<td valign="top">great idea with the translucent sheet and great title. I wish the sheet was not so wrinkled though.</td>', 'great idea with the translucent sheet and great title. I wish the sheet was not so wrinkled though.', '2006-02-05 08:29:24.000000', NULL, 1),
(2123667, 290333, 8624, '<td valign="top">cool - it almost looks as if you are paddling across water.</td>', 'cool - it almost looks as if you are paddling across water.', '2006-02-05 08:31:27.000000', NULL, 1),
(2123668, 289976, 8624, '<td valign="top">very cool lighting and point of view. I''ll be interested in finding out how you created this one.</td>', 'very cool lighting and point of view. I''ll be interested in finding out how you created this one.', '2006-02-05 08:31:43.000000', NULL, 1),
(2123672, 289913, 8624, '<td valign="top">hey - that shadow must be my kids who often have the same reaction to me! funny. little too hot on your back and the door is a little distracting, but a great concept.</td>', 'hey - that shadow must be my kids who often have the same reaction to me! funny. little too hot on your back and the door is a little distracting, but a great concept.', '2006-02-05 08:33:07.000000', NULL, 1),
(2123750, 290155, 35451, '<td valign="top">My top Pick!</td>', 'My top Pick!', '2006-02-05 09:32:14.000000', NULL, 1),
(2123898, 290335, 43682, '<td valign="top">very dark background</td>', 'very dark background', '2006-02-05 10:50:32.000000', NULL, 1),
(2123904, 290296, 20210, '<td valign="top">might be better with more contrast, since the dynamic range is most of the interest.</td>', 'might be better with more contrast, since the dynamic range is most of the interest.', '2006-02-05 10:57:15.000000', NULL, 1),
(2123906, 290104, 20210, '<td valign="top">a bigger version will yield you a higher score!  but a clever setup on this one.</td>', 'a bigger version will yield you a higher score!  but a clever setup on this one.', '2006-02-05 10:59:12.000000', NULL, 1),
(2123909, 290287, 20210, '<td valign="top">Feels off-level a bit.  Interesting idea, but a bit too little "photography" feel for me.</td>', 'Feels off-level a bit.  Interesting idea, but a bit too little "photography" feel for me.', '2006-02-05 11:00:53.000000', NULL, 1),
(2123911, 290056, 20210, '<td valign="top">very interesting perspective</td>', 'very interesting perspective', '2006-02-05 11:01:13.000000', NULL, 1),
(2123913, 290107, 20210, '<td valign="top">Cute title.  The subject (your shadow) doesn''t dominate the composition enough, too many other shadows fighting for attention.</td>', 'Cute title.  The subject (your shadow) doesn''t dominate the composition enough, too many other shadows fighting for attention.', '2006-02-05 11:01:57.000000', NULL, 1),
(2123914, 290188, 20210, '<td valign="top">a little higher contrast might help this "pop" more.  cute concept.</td>', 'a little higher contrast might help this "pop" more.  cute concept.', '2006-02-05 11:02:33.000000', NULL, 1),
(2123916, 290090, 20210, '<td valign="top">compelling composition, nice work.</td>', 'compelling composition, nice work.', '2006-02-05 11:02:47.000000', NULL, 1),
(2123918, 289913, 20210, '<td valign="top">great idea, I crave a more interesting location for it!</td>', 'great idea, I crave a more interesting location for it!', '2006-02-05 11:03:28.000000', NULL, 1),
(2123920, 290321, 20210, '<td valign="top">great composition, I love the simple B&amp;W, vertical stripes, and the lamp in the corner.</td>', 'great composition, I love the simple B&W, vertical stripes, and the lamp in the corner.', '2006-02-05 11:04:12.000000', NULL, 1),
(2123921, 290327, 20210, '<td valign="top">Very moody, great lighting!</td>', 'Very moody, great lighting!', '2006-02-05 11:05:05.000000', NULL, 1),
(2123933, 290182, 13688, '<td valign="top">looks like you put some time into this setup, but it''s too small for me to figure out what is going on.  i like how the top has been squared off.  i''m left wondering...</td>', 'looks like you put some time into this setup, but it''s too small for me to figure out what is going on.  i like how the top has been squared off.  i''m left wondering...', '2006-02-05 11:10:18.000000', NULL, 1),
(2123944, 290184, 13688, '<td valign="top">nice lighting.  very dynamic composition.  think it would have done extremely well in "road"</td>', 'nice lighting.  very dynamic composition.  think it would have done extremely well in "road"', '2006-02-05 11:14:07.000000', NULL, 1),
(2123953, 290249, 13688, '<td valign="top">nice high key.  makes you think for a couple of seconds.</td>', 'nice high key.  makes you think for a couple of seconds.', '2006-02-05 11:17:04.000000', NULL, 1),
(2123972, 289913, 13688, '<td valign="top">odd choice of locale, but very clever idea.</td>', 'odd choice of locale, but very clever idea.', '2006-02-05 11:22:28.000000', NULL, 1),
(2123981, 290226, 13688, '<td valign="top">nice pun, interesting idea to project the shadow in front of you.  whish your sheet was smooth</td>', 'nice pun, interesting idea to project the shadow in front of you.  whish your sheet was smooth', '2006-02-05 11:25:02.000000', NULL, 1),
(2123988, 290025, 34059, '<td valign="top">if I could vote, this would be a 10! very original interpretation of the challenge, well executed and composed. My best compliments!</td>', 'if I could vote, this would be a 10! very original interpretation of the challenge, well executed and composed. My best compliments!', '2006-02-05 11:28:24.000000', NULL, 1),
(2123995, 290101, 13688, '<td valign="top">interesting.  really like the post process burning, though the legs don''t seem to match what you did with the upper body.  but don''t listen to me it''s your art.  like the odd border and the softness around the fringe.  upon real close inspection some sections seem to be over sharpened and the right side of her outline seems messy.  enjoyed looking at it.</td>', 'interesting.  really like the post process burning, though the legs don''t seem to match what you did with the upper body.  but don''t listen to me it''s your art.  like the odd border and the softness around the fringe.  upon real close inspection some sections seem to be over sharpened and the right side of her outline seems messy.  enjoyed looking at it.', '2006-02-05 11:35:56.000000', NULL, 1),
(2123999, 289907, 13688, '<td valign="top">nice crisp outline, which as far as i can tell is extremely difficult to attain.  you have left an awkward amount of space at the top, perhaps to simulate falling.  would have liked to see all four limbs, as this current pose looks like you''re holding the camera, which takes away from it a bit for me.</td>', 'nice crisp outline, which as far as i can tell is extremely difficult to attain.  you have left an awkward amount of space at the top, perhaps to simulate falling.  would have liked to see all four limbs, as this current pose looks like you''re holding the camera, which takes away from it a bit for me.', '2006-02-05 11:39:38.000000', NULL, 1),
(2124004, 290050, 13688, '<td valign="top">very basic, but very intriguing.  like the coloring and the straightness of the lines.  only thing i would have changed is to remove the shadow just to the right of his outline.  i think i would have liked the composition more with that entire area open space.</td>', 'very basic, but very intriguing.  like the coloring and the straightness of the lines.  only thing i would have changed is to remove the shadow just to the right of his outline.  i think i would have liked the composition more with that entire area open space.', '2006-02-05 11:43:44.000000', NULL, 1),
(2124013, 289976, 13688, '<td valign="top">cool idea.  that green light area is an interesting juxtaposition with the main subject''s lighting.  very good, though i find it odd having him staring out of a closed parking garage.  did he forget to get his parking pass validated at the movie?</td>', 'cool idea.  that green light area is an interesting juxtaposition with the main subject''s lighting.  very good, though i find it odd having him staring out of a closed parking garage.  did he forget to get his parking pass validated at the movie?', '2006-02-05 11:52:57.000000', NULL, 1),
(2124058, 289976, 15479, '<td valign="top">Brilliant idea, and awesomely executed. The first 10 of this challenge.</td>', 'Brilliant idea, and awesomely executed. The first 10 of this challenge.', '2006-02-05 12:44:35.000000', NULL, 1),
(2124067, 290335, 16648, '<td valign="top">too dark on my monitor to tell what it is.</td>', 'too dark on my monitor to tell what it is.', '2006-02-05 12:53:35.000000', NULL, 1),
(2124071, 290184, 16648, '<td valign="top">Hmmm...nice pic, but i am asking myself one question - is this a creative approach to the challenge or are you trying to circumvent the descrpition? Was your effort put into meeting the challenge or trying to work around it? Since I don''t see your shadow, you failed to capture it. Does that make you a lousy photographer, the inability to capture a simple subject? Or are you having troubles following simple rules? Hmmm...not so simple, but then it is.</td>', 'Hmmm...nice pic, but i am asking myself one question - is this a creative approach to the challenge or are you trying to circumvent the descrpition? Was your effort put into meeting the challenge or trying to work around it? Since I don''t see your shadow, you failed to capture it. Does that make you a lousy photographer, the inability to capture a simple subject? Or are you having troubles following simple rules? Hmmm...not so simple, but then it is.', '2006-02-05 12:58:15.000000', NULL, 1),
(2124078, 290182, 16648, '<td valign="top">Pic is bit too small. Check the tutorial section for resizing images for challenge entries.</td>', 'Pic is bit too small. Check the tutorial section for resizing images for challenge entries.', '2006-02-05 13:01:14.000000', NULL, 1),
(2124083, 290249, 20462, '<td valign="top">Suprised this had to be validated.  Is "reserved" supposed to be a joke?  I am assuming the location is well placed.  The composition works for me.</td>', 'Suprised this had to be validated.  Is "reserved" supposed to be a joke?  I am assuming the location is well placed.  The composition works for me.', '2006-02-05 13:03:46.000000', NULL, 1),
(2124086, 290044, 20462, '<td valign="top">Tough to do something like this well enough to attach the viewer.  If the shadow was sharper.....</td>', 'Tough to do something like this well enough to attach the viewer.  If the shadow was sharper.....', '2006-02-05 13:04:34.000000', NULL, 1),
(2124088, 290269, 16648, '<td valign="top">a bit dark overall on my monitor</td>', 'a bit dark overall on my monitor', '2006-02-05 13:04:42.000000', NULL, 1),
(2124090, 290301, 20462, '<td valign="top">are you clapping?  or making one of those shadow puppets?  I see a chicken standing next to a hen...</td>', 'are you clapping?  or making one of those shadow puppets?  I see a chicken standing next to a hen...', '2006-02-05 13:05:35.000000', NULL, 1),
(2124093, 289920, 20462, '<td valign="top">title assists the photo.  The colors are little bold. Perhaps if there were simply two or three shadows this could be really well done.  nice idea.</td>', 'title assists the photo.  The colors are little bold. Perhaps if there were simply two or three shadows this could be really well done.  nice idea.', '2006-02-05 13:06:19.000000', NULL, 1),
(2124094, 290329, 20462, '<td valign="top">just put an archaic throne there, and it looks like a king proceeding to his perch..  I like the shadows on the stairs.</td>', 'just put an archaic throne there, and it looks like a king proceeding to his perch..  I like the shadows on the stairs.', '2006-02-05 13:07:06.000000', NULL, 1),
(2124096, 290153, 20462, '<td valign="top">done many times here.  Would be fairly surprised for this to do too well, but I think it is well conceived.  The ribbon is cooler than the shadow though...</td>', 'done many times here.  Would be fairly surprised for this to do too well, but I think it is well conceived.  The ribbon is cooler than the shadow though...', '2006-02-05 13:08:05.000000', NULL, 1),
(2124098, 290335, 20462, '<td valign="top">everyone always complains about my photos being too dark sometimes when I do a black silhouette.   I usually disagree because I calibrate my monitor and check it out on others sometimes.  But this is too dark to convey a cool subject...</td>', 'everyone always complains about my photos being too dark sometimes when I do a black silhouette.   I usually disagree because I calibrate my monitor and check it out on others sometimes.  But this is too dark to convey a cool subject...', '2006-02-05 13:09:10.000000', NULL, 1),
(2124099, 290140, 20462, '<td valign="top">The grid on which is shadow is portrayed is so expertly positioned on the photo that it makes the shadow more interesting.  good care on alignment and composition.</td>', 'The grid on which is shadow is portrayed is so expertly positioned on the photo that it makes the shadow more interesting.  good care on alignment and composition.', '2006-02-05 13:09:57.000000', NULL, 1),
(2124100, 290072, 20462, '<td valign="top">wow, that is some weird looking water.  more like jelly-ish hair gel or something.  the concept of the shadow attempting to grasp something "real" is classic.</td>', 'wow, that is some weird looking water.  more like jelly-ish hair gel or something.  the concept of the shadow attempting to grasp something "real" is classic.', '2006-02-05 13:10:50.000000', NULL, 1),
(2124101, 290211, 20462, '<td valign="top">The black and white photo is nicely balanced.  But the shadow only slightly heightens the viewing experience.</td>', 'The black and white photo is nicely balanced.  But the shadow only slightly heightens the viewing experience.', '2006-02-05 13:11:25.000000', NULL, 1),
