(2128958, 290300, 42125, '<td valign="top">Disagree but the picture is good.</td>', 'Disagree but the picture is good.', '2006-02-07 06:39:35.000000', NULL, 1),
(2128959, 289945, 42125, '<td valign="top">Nice and clean.</td>', 'Nice and clean.', '2006-02-07 06:39:51.000000', NULL, 1),
(2128963, 290269, 42125, '<td valign="top">There is an old piano where thay play it hot. Nice shot.</td>', 'There is an old piano where thay play it hot. Nice shot.', '2006-02-07 06:43:57.000000', NULL, 1),
(2129410, 290277, 27482, '<td valign="top">Is that you Joey?  Anyway, nice picture, whoever it is, definately one of the better shots in a rather mediocre challenge, good enough for an 8 from me :D</td>', 'Is that you Joey?  Anyway, nice picture, whoever it is, definately one of the better shots in a rather mediocre challenge, good enough for an 8 from me :D', '2006-02-07 10:07:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2129421, 290283, 27482, '<td valign="top">Nice composition but I am not fond of the soft focus at all so I only gave it a 5.</td>', 'Nice composition but I am not fond of the soft focus at all so I only gave it a 5.', '2006-02-07 10:15:37.000000', NULL, 1),
(2129425, 290327, 27482, '<td valign="top">Pretty cool shot, love the ominous feel to it.</td>', 'Pretty cool shot, love the ominous feel to it.', '2006-02-07 10:16:53.000000', NULL, 1),
(2130031, 290078, 52943, '<td valign="top">Very creepy/scary. Nice job.</td>', 'Very creepy/scary. Nice job.', '2006-02-07 15:10:26.000000', NULL, 1),
(2130089, 289945, 42984, '<td valign="top">Great concept</td>', 'Great concept', '2006-02-07 15:35:31.000000', NULL, 1),
(2130091, 290128, 42984, '<td valign="top">Love the imposing and over bearing feel of this</td>', 'Love the imposing and over bearing feel of this', '2006-02-07 15:35:58.000000', NULL, 1),
(2130092, 290301, 42984, '<td valign="top">Ok, this has me baffled</td>', 'Ok, this has me baffled', '2006-02-07 15:36:21.000000', NULL, 1),
(2130094, 290170, 42984, '<td valign="top">It''s really just too blurred, I guess that''s from getting in close</td>', 'It''s really just too blurred, I guess that''s from getting in close', '2006-02-07 15:36:54.000000', NULL, 1),
(2130096, 290194, 42984, '<td valign="top">Great size in relation to subject ... well done</td>', 'Great size in relation to subject ... well done', '2006-02-07 15:37:28.000000', NULL, 1),
(2130098, 290335, 42984, '<td valign="top">I guess by now you''ve realised it''s too dark</td>', 'I guess by now you''ve realised it''s too dark', '2006-02-07 15:37:52.000000', NULL, 1),
(2130101, 290073, 42984, '<td valign="top">The texture of the wall andf the simplcity are attractive</td>', 'The texture of the wall andf the simplcity are attractive', '2006-02-07 15:38:20.000000', NULL, 1),
(2130104, 290184, 42984, '<td valign="top">Great shot, but it''s not about your shadow</td>', 'Great shot, but it''s not about your shadow', '2006-02-07 15:38:52.000000', NULL, 1),
(2130106, 290226, 42984, '<td valign="top">Different approach which is attractive</td>', 'Different approach which is attractive', '2006-02-07 15:39:13.000000', NULL, 1),
(2130109, 290288, 42984, '<td valign="top">Yeah my mom used to do that too ... grrr. This is a god creative take on the challenge</td>', 'Yeah my mom used to do that too ... grrr. This is a god creative take on the challenge', '2006-02-07 15:40:16.000000', NULL, 1),
(2130110, 290105, 42984, '<td valign="top">The double-light source and the predicyability of it sort of works against a high score even though its competent</td>', 'The double-light source and the predicyability of it sort of works against a high score even though its competent', '2006-02-07 15:41:03.000000', NULL, 1),
(2130111, 290148, 42984, '<td valign="top">Sort of predictble which is what has made this such a tough challenge in such a short time</td>', 'Sort of predictble which is what has made this such a tough challenge in such a short time', '2006-02-07 15:41:43.000000', NULL, 1),
(2130117, 290145, 42984, '<td valign="top">Cool use of colour. The floor bugs me because it looks like its tipping over. That''s clearly what you intended ... just that it doesn''t sit right with this viewer</td>', 'Cool use of colour. The floor bugs me because it looks like its tipping over. That''s clearly what you intended ... just that it doesn''t sit right with this viewer', '2006-02-07 15:42:58.000000', NULL, 1),
(2130118, 290279, 42984, '<td valign="top">Oooh, yes. simple, clean and very well designed</td>', 'Oooh, yes. simple, clean and very well designed', '2006-02-07 15:43:30.000000', NULL, 1),
(2130127, 290180, 42984, '<td valign="top">Clever, perhaps a little too predictable and maybe setting the plugs off-centre would help</td>', 'Clever, perhaps a little too predictable and maybe setting the plugs off-centre would help', '2006-02-07 15:45:08.000000', NULL, 1),
(2130144, 290259, 42984, '<td valign="top">Love the colours, and the composition. The neutral space in the window just serves to highlight the shadow .. is it yours?</td>', 'Love the colours, and the composition. The neutral space in the window just serves to highlight the shadow .. is it yours?', '2006-02-07 15:50:34.000000', NULL, 1),
(2130145, 290283, 42984, '<td valign="top">Sorry, I do not like gratuitous nudity</td>', 'Sorry, I do not like gratuitous nudity', '2006-02-07 15:51:17.000000', NULL, 1),
(2130148, 290155, 42984, '<td valign="top">Now that''s pretty cool. The efect is really daramtic and mysterious</td>', 'Now that''s pretty cool. The efect is really daramtic and mysterious', '2006-02-07 15:51:57.000000', NULL, 1),
(2130153, 290139, 42984, '<td valign="top">Very good treatment of the subject. Great sympolism and well crafted</td>', 'Very good treatment of the subject. Great sympolism and well crafted', '2006-02-07 15:53:12.000000', NULL, 1),
(2130155, 290329, 42984, '<td valign="top">Perhaps just too many elements conflicting with each other to score highly</td>', 'Perhaps just too many elements conflicting with each other to score highly', '2006-02-07 15:53:39.000000', NULL, 1),
(2130159, 290324, 42984, '<td valign="top">Great creativity and it works. Difficult to see how it''s done and that draws one into the image</td>', 'Great creativity and it works. Difficult to see how it''s done and that draws one into the image', '2006-02-07 15:54:21.000000', NULL, 1),
(2130164, 290296, 42984, '<td valign="top">I don''t get it. Is this your shadow strobed? It''s hard to be sure it is about you and your shadow. If it is, it''s one of the best I have seen</td>', 'I don''t get it. Is this your shadow strobed? It''s hard to be sure it is about you and your shadow. If it is, it''s one of the best I have seen', '2006-02-07 15:55:16.000000', NULL, 1),
(2130167, 290184, 43565, '<td valign="top">Hmmm, I don''t see a shadow!</td>', 'Hmmm, I don''t see a shadow!', '2006-02-07 15:56:06.000000', NULL, 1),
(2130168, 290101, 42984, '<td valign="top">The messy border makes the image look amateur. Am not at all fond of gratuitous nudity either.</td>', 'The messy border makes the image look amateur. Am not at all fond of gratuitous nudity either.', '2006-02-07 15:56:10.000000', NULL, 1),
(2130172, 290130, 42984, '<td valign="top">Pity there''s two of these right beside each other on my thumbnail screen. Yours is best :)</td>', 'Pity there''s two of these right beside each other on my thumbnail screen. Yours is best :)', '2006-02-07 15:56:52.000000', NULL, 1),
(2130194, 290316, 43565, '<td valign="top">The shadow is not sensual to me.</td>', 'The shadow is not sensual to me.', '2006-02-07 16:05:13.000000', NULL, 1),
(2130200, 289961, 43565, '<td valign="top">This does not seem to be a shot of your shadow.</td>', 'This does not seem to be a shot of your shadow.', '2006-02-07 16:07:47.000000', NULL, 1),
(2130353, 290184, 5112, '<td valign="top">Updating comment:<br/> <br/>Beautiful shot.  I love the dynamic swing to the road/landscape, the sense of travelling.  I love the colour scheme (grey/tan and blue with bits of yellow and white).  I love the pattern of shadows and light!<br/> <br/>I hope you do well.  The image will likely score much lower than it deserves because of people''s interpretation of the challenge topic.  You should have entered it to "Roads"!  :)<br/></td>', 'Updating comment: Beautiful shot.  I love the dynamic swing to the road/landscape, the sense of travelling.  I love the colour scheme (grey/tan and blue with bits of yellow and white).  I love the pattern of shadows and light! I hope you do well.  The image will likely score much lower than it deserves because of people''s interpretation of the challenge topic.  You should have entered it to "Roads"!  :)', '2006-02-07 17:04:18.000000', NULL, 1),
(2130356, 290262, 22619, '<td valign="top">A little too dark in my opinion, but the shadows shape does have interest</td>', 'A little too dark in my opinion, but the shadows shape does have interest', '2006-02-07 17:07:41.000000', NULL, 1),
(2130358, 290078, 22619, '<td valign="top">Good work. The lighting on the "soon-to-be victim" is uneven. Perhaps intentional, but IMHO it would look better if it were more even. Either all in slight shadow, or all lit.</td>', 'Good work. The lighting on the "soon-to-be victim" is uneven. Perhaps intentional, but IMHO it would look better if it were more even. Either all in slight shadow, or all lit.', '2006-02-07 17:09:07.000000', NULL, 1),
(2130359, 290192, 22619, '<td valign="top">Too dark. Not enough contrast.</td>', 'Too dark. Not enough contrast.', '2006-02-07 17:09:50.000000', NULL, 1),
(2130362, 290098, 22619, '<td valign="top">I like it, I like it. Maybe could crop off a bit more on the bottom, leaving the shadows to trail off the picture.</td>', 'I like it, I like it. Maybe could crop off a bit more on the bottom, leaving the shadows to trail off the picture.', '2006-02-07 17:11:21.000000', NULL, 1),
(2130364, 290269, 22619, '<td valign="top">Nice composition, but a bit dark in my opinion.</td>', 'Nice composition, but a bit dark in my opinion.', '2006-02-07 17:11:58.000000', NULL, 1),
(2130365, 290213, 22619, '<td valign="top">well done</td>', 'well done', '2006-02-07 17:12:10.000000', NULL, 1),
(2130368, 290295, 22619, '<td valign="top">Nice. I like that its not the usual monochromatic shadow. Well done.</td>', 'Nice. I like that its not the usual monochromatic shadow. Well done.', '2006-02-07 17:12:45.000000', NULL, 1),
(2130371, 290130, 22619, '<td valign="top">Nice recreation</td>', 'Nice recreation', '2006-02-07 17:13:33.000000', NULL, 1),
(2130672, 289913, 52889, '<td valign="top">love it very original</td>', 'love it very original', '2006-02-07 19:26:45.000000', NULL, 1),
(2130679, 290154, 52889, '<td valign="top">great photo and original as well!</td>', 'great photo and original as well!', '2006-02-07 19:30:38.000000', NULL, 1),
(2130752, 290154, 44743, '<td valign="top">Clever idea.  The hat makes the shot.</td>', 'Clever idea.  The hat makes the shot.', '2006-02-07 19:54:58.000000', NULL, 1),
(2130761, 290228, 44743, '<td valign="top">Looks like a nice shot, but a larger image would make it easier to see.</td>', 'Looks like a nice shot, but a larger image would make it easier to see.', '2006-02-07 19:56:48.000000', NULL, 1),
(2130771, 290186, 44743, '<td valign="top">I like the title.  The shadow itself, though, doesn''t seem terribly interesting.</td>', 'I like the title.  The shadow itself, though, doesn''t seem terribly interesting.', '2006-02-07 19:58:47.000000', NULL, 1),
(2130777, 290253, 44743, '<td valign="top">Wow... that''s a creepy shadow.  Nice look of fear.  I''ll be curious to see the details of how you did this one.</td>', 'Wow... that''s a creepy shadow.  Nice look of fear.  I''ll be curious to see the details of how you did this one.', '2006-02-07 20:00:46.000000', NULL, 1),
(2130780, 290330, 44743, '<td valign="top">Very nice, crisp shadow.</td>', 'Very nice, crisp shadow.', '2006-02-07 20:02:00.000000', NULL, 1),
(2130789, 289961, 44743, '<td valign="top">Clever spin on this challenge.  I like it.</td>', 'Clever spin on this challenge.  I like it.', '2006-02-07 20:04:08.000000', NULL, 1),
(2130817, 290295, 44743, '<td valign="top">On the plus side, I really like that you have created "colored" shadows with the bottle &amp; glass.  The multiple shadows (multiple light sources?), though, seem pretty distracting.  I find myself looking at the illusion of movement, rather than at the subject''s contemplation.</td>', 'On the plus side, I really like that you have created "colored" shadows with the bottle & glass.  The multiple shadows (multiple light sources?), though, seem pretty distracting.  I find myself looking at the illusion of movement, rather than at the subject''s contemplation.', '2006-02-07 20:09:03.000000', NULL, 1),
(2130824, 290194, 44743, '<td valign="top">Very nicely done!  The hands are positioned perfectly on the two ledges-- great attention to detail.</td>', 'Very nicely done!  The hands are positioned perfectly on the two ledges-- great attention to detail.', '2006-02-07 20:10:11.000000', NULL, 1),
(2130828, 290104, 44743, '<td valign="top">I like the concept for this shot &amp; a fun title.  A bigger image would be very helpful, though.</td>', 'I like the concept for this shot & a fun title.  A bigger image would be very helpful, though.', '2006-02-07 20:11:33.000000', NULL, 1),
(2130842, 290084, 44743, '<td valign="top">The wavy curtains do give an eerie feel to go along with your title.  However, the shot looks a little bland overall-- everything is very gray, and it''s hard to make out any definition in the shadow.</td>', 'The wavy curtains do give an eerie feel to go along with your title.  However, the shot looks a little bland overall-- everything is very gray, and it''s hard to make out any definition in the shadow.', '2006-02-07 20:13:51.000000', NULL, 1),
(2130844, 290211, 44743, '<td valign="top">Nice, ominous look.</td>', 'Nice, ominous look.', '2006-02-07 20:14:17.000000', NULL, 1),
(2130862, 290078, 44743, '<td valign="top">Very nice.  The shadow &amp; girl reading are a great combo-- it almost feels as if we can see the girl''s thoughts while she reads.  One of my favorites for this challenge.</td>', 'Very nice.  The shadow & girl reading are a great combo-- it almost feels as if we can see the girl''s thoughts while she reads.  One of my favorites for this challenge.', '2006-02-07 20:18:31.000000', NULL, 1),
(2130866, 290130, 44743, '<td valign="top">Great idea.  The lighting around the knife is perhaps a bit harsh?</td>', 'Great idea.  The lighting around the knife is perhaps a bit harsh?', '2006-02-07 20:19:49.000000', NULL, 1),
(2130869, 290049, 44743, '<td valign="top">Neat shot-- searching for the figure''s shadow gives an almost "where''s waldo" feel to it.</td>', 'Neat shot-- searching for the figure''s shadow gives an almost "where''s waldo" feel to it.', '2006-02-07 20:21:44.000000', NULL, 1),
(2130872, 290277, 44743, '<td valign="top">I like the lighting and tone of the image.  I wish the shadow had a bit more discernable shape, though.</td>', 'I like the lighting and tone of the image.  I wish the shadow had a bit more discernable shape, though.', '2006-02-07 20:23:29.000000', NULL, 1),
(2130917, 290322, 44743, '<td valign="top">Neat idea.  Very original.  Defintely has a genie / bottle feel.  Only concern is the light in the paper bag-- it seems a bit too defined as a flashlight.  Perhaps moving it further back in the bag would make it less obvious?</td>', 'Neat idea.  Very original.  Defintely has a genie / bottle feel.  Only concern is the light in the paper bag-- it seems a bit too defined as a flashlight.  Perhaps moving it further back in the bag would make it less obvious?', '2006-02-07 20:36:03.000000', NULL, 1),
(2130921, 290335, 44743, '<td valign="top">It''s a great idea for a shadow shot &amp; a nice title.  I just wish the blue were a bit brighter so it was easier to see the shadow.</td>', 'It''s a great idea for a shadow shot & a nice title.  I just wish the blue were a bit brighter so it was easier to see the shadow.', '2006-02-07 20:37:02.000000', NULL, 1),
(2130927, 290153, 44743, '<td valign="top">hehe... very clever.  I just wish the shadow was a bit darker and/or was better defined at the outline.  Perhaps a single light source would have helped?</td>', 'hehe... very clever.  I just wish the shadow was a bit darker and/or was better defined at the outline.  Perhaps a single light source would have helped?', '2006-02-07 20:38:45.000000', NULL, 1),
(2130934, 289976, 44743, '<td valign="top">Very impressive.  Nicely done!</td>', 'Very impressive.  Nicely done!', '2006-02-07 20:40:32.000000', NULL, 1),
(2130941, 290170, 44743, '<td valign="top">Excellent idea.  Immediately recognizable as the Sistene Chapel.  Overall, though, it feels a bit fuzzy.  A bit crisper definition of the shadow might have helped.</td>', 'Excellent idea.  Immediately recognizable as the Sistene Chapel.  Overall, though, it feels a bit fuzzy.  A bit crisper definition of the shadow might have helped.', '2006-02-07 20:42:43.000000', NULL, 1),
(2130942, 290285, 44743, '<td valign="top">Amazing colors!</td>', 'Amazing colors!', '2006-02-07 20:43:01.000000', NULL, 1),
(2130946, 290300, 44743, '<td valign="top">Clever shot!  I like the halo.</td>', 'Clever shot!  I like the halo.', '2006-02-07 20:44:56.000000', NULL, 1),
(2130959, 290279, 44743, '<td valign="top">Nice.  Simple and powerful.</td>', 'Nice.  Simple and powerful.', '2006-02-07 20:46:45.000000', NULL, 1),
(2130962, 289913, 35786, '<td valign="top">my fave! 10!!! :0)</td>', 'my fave! 10!!! :0)', '2006-02-07 20:48:02.000000', NULL, 1),
(2131491, 290277, 51143, '<td valign="top">Wow!  I love the color in this.</td>', 'Wow!  I love the color in this.', '2006-02-07 23:30:18.000000', NULL, 1),
(2132121, 290025, 50217, '<td valign="top">wow.. this is acrobatic! very nice.</td>', 'wow.. this is acrobatic! very nice.', '2006-02-08 01:18:32.000000', NULL, 1),
(2132142, 290078, 35786, '<td valign="top">for some reason this reminds me of a scene from an old movie. I really like it!</td>', 'for some reason this reminds me of a scene from an old movie. I really like it!', '2006-02-08 01:25:15.000000', NULL, 1),
(2132278, 290325, 39243, '<td valign="top">nice - great remake</td>', 'nice - great remake', '2006-02-08 02:09:00.000000', NULL, 1),
(2132288, 290296, 39243, '<td valign="top">I hope you don''t mind some constructive crit. - the title of the challenge was "your shadow II" if this is your shadow I am not exactly sure what planet you are from. I would not understand the photo without the title and even then it is an extreeeeeeme stretch. The photo itself is difficult to look at - kind of makes me sea sick. Good luck - I did not mean to sound harsh but when I give such a low score I figure I should explain why.</td>', 'I hope you don''t mind some constructive crit. - the title of the challenge was "your shadow II" if this is your shadow I am not exactly sure what planet you are from. I would not understand the photo without the title and even then it is an extreeeeeeme stretch. The photo itself is difficult to look at - kind of makes me sea sick. Good luck - I did not mean to sound harsh but when I give such a low score I figure I should explain why.', '2006-02-08 02:13:51.000000', NULL, 1),
(2132291, 290025, 39243, '<td valign="top">I think this might have done better if the actual person was not in the photo. Just my opinion of course but I like the idea.</td>', 'I think this might have done better if the actual person was not in the photo. Just my opinion of course but I like the idea.', '2006-02-08 02:15:01.000000', NULL, 1),
(2132677, 289913, 30690, '<td valign="top">Absolutely hilarious!</td>', 'Absolutely hilarious!', '2006-02-08 05:13:58.000000', NULL, 1),
(2132681, 290025, 30690, '<td valign="top">Must be tiring to hold on to that position. Would have helped emphasize your picture and title if you throw in a few props to show the "windy" impact. Then again, I must say its an innovative titling.</td>', 'Must be tiring to hold on to that position. Would have helped emphasize your picture and title if you throw in a few props to show the "windy" impact. Then again, I must say its an innovative titling.', '2006-02-08 05:16:27.000000', NULL, 1),
(2132685, 290277, 30690, '<td valign="top">Love the pensive mood! Never thought I could dislike my own shadow that much until I saw this picture.</td>', 'Love the pensive mood! Never thought I could dislike my own shadow that much until I saw this picture.', '2006-02-08 05:20:17.000000', NULL, 1),
(2133555, 290321, 39988, '<td valign="top">appropriate symbolism</td>', 'appropriate symbolism', '2006-02-08 11:42:52.000000', NULL, 1),
(2133564, 290249, 39988, '<td valign="top">Like the pattern use</td>', 'Like the pattern use', '2006-02-08 11:46:03.000000', NULL, 1),
(2133568, 290153, 39988, '<td valign="top">I get it</td>', 'I get it', '2006-02-08 11:46:50.000000', NULL, 1),
(2133573, 290288, 39988, '<td valign="top">How did your head change shape?</td>', 'How did your head change shape?', '2006-02-08 11:47:47.000000', NULL, 1),
(2133575, 290279, 39988, '<td valign="top">Terrific relation of shadow and lighting, I like it</td>', 'Terrific relation of shadow and lighting, I like it', '2006-02-08 11:48:26.000000', NULL, 1),
(2133578, 289961, 39988, '<td valign="top">This appeals to me</td>', 'This appeals to me', '2006-02-08 11:49:06.000000', NULL, 1),
(2133601, 290226, 39988, '<td valign="top">Different perspective- nice</td>', 'Different perspective- nice', '2006-02-08 11:56:58.000000', NULL, 1),
(2133670, 290249, 3087, '<td valign="top">Nice idea and I really like the composition too. What I don''t like is the utter whiteness of that wall... I don''t know whether you''ve blown it out in the exposure (deliberately or otherwise) or have cleaned up what little texture was remaining during post-processing. Certainly I''m not doubting that it''s legal - I''m sure it is. But I don''t like it. I''d much rather see a little texture on that wall too. The lack of it takes away from the gritty nature of the shot overall.</td>', 'Nice idea and I really like the composition too. What I don''t like is the utter whiteness of that wall... I don''t know whether you''ve blown it out in the exposure (deliberately or otherwise) or have cleaned up what little texture was remaining during post-processing. Certainly I''m not doubting that it''s legal - I''m sure it is. But I don''t like it. I''d much rather see a little texture on that wall too. The lack of it takes away from the gritty nature of the shot overall.', '2006-02-08 12:14:11.000000', NULL, 1),
(2133682, 290325, 3087, '<td valign="top">Simple, fun idea!</td>', 'Simple, fun idea!', '2006-02-08 12:15:27.000000', NULL, 1),
(2133691, 290277, 3087, '<td valign="top">Nice environmental portrait... I like all the detail and textures of the environment, the simple pose of the subject and the yellow light too. Works really well.</td>', 'Nice environmental portrait... I like all the detail and textures of the environment, the simple pose of the subject and the yellow light too. Works really well.', '2006-02-08 12:16:14.000000', NULL, 1),
(2133699, 290128, 3087, '<td valign="top">Lighting and location provide real sense of drama and surrealism. I like the lines/ pattern of the wall surface and the strange shadows at top and bottom left. I also like the capture of motion in the subject, the colour of the jacket and the hulking form of the main shadow. Altogether a great pic!</td>', 'Lighting and location provide real sense of drama and surrealism. I like the lines/ pattern of the wall surface and the strange shadows at top and bottom left. I also like the capture of motion in the subject, the colour of the jacket and the hulking form of the main shadow. Altogether a great pic!', '2006-02-08 12:17:31.000000', NULL, 1),
(2133705, 290316, 3087, '<td valign="top">An interesting composition and I like the positioning of the body within the frame. The nipple is almost a mark of punctuation there in the corner. The shadow itself disappoints me though - I''d like to see more form to it.</td>', 'An interesting composition and I like the positioning of the body within the frame. The nipple is almost a mark of punctuation there in the corner. The shadow itself disappoints me though - I''d like to see more form to it.', '2006-02-08 12:18:40.000000', NULL, 1),
(2133716, 289976, 3087, '<td valign="top">Absolutely great choice of location in which to stage this shot - the mysterial industrial nature, the strong greens and yellows and the gritty textures are very suggestive of a futuristic sci-fi setting. I''m guessing the "shadow" is a black paper cutout into which your real shadow falls and is lost? Great composition, great colours, great textures, great lighting, great idea!</td>', 'Absolutely great choice of location in which to stage this shot - the mysterial industrial nature, the strong greens and yellows and the gritty textures are very suggestive of a futuristic sci-fi setting. I''m guessing the "shadow" is a black paper cutout into which your real shadow falls and is lost? Great composition, great colours, great textures, great lighting, great idea!', '2006-02-08 12:20:55.000000', NULL, 1),
(2134003, 289913, 50225, '<td valign="top">I like this one for its humorous aspect.</td>', 'I like this one for its humorous aspect.', '2006-02-08 13:33:27.000000', NULL, 1),
(2134820, 290259, 3087, '<td valign="top">Interesting image! The presentation clearly places more emphasis on the large open doorway than the person themself... is that part of the message? Perhaps it''s an unconscious clue to the self-effacing personality? Or maybe I''m reading too much into it? I do like the bright yellow (my fave colour) and the framing provided by the door. The shutters give some interesting detail - without them it would be too stark - it''s verging on that anyway. The composition is jarring but that''s actually not a bad thing as it adds to the impact of the image itself.</td>', 'Interesting image! The presentation clearly places more emphasis on the large open doorway than the person themself... is that part of the message? Perhaps it''s an unconscious clue to the self-effacing personality? Or maybe I''m reading too much into it? I do like the bright yellow (my fave colour) and the framing provided by the door. The shutters give some interesting detail - without them it would be too stark - it''s verging on that anyway. The composition is jarring but that''s actually not a bad thing as it adds to the impact of the image itself.', '2006-02-08 17:00:44.000000', NULL, 1),
